import React, { useState, useEffect } from 'react';

const PageCounter = () => {
    const [views, setViews] = useState(0);

    useEffect(() => {
        // Replace 'infinitylbsl.com.np' with your actual domain or a unique key
        const namespace = 'infinitylbsl.com.np';
        const key = 'home-page-visits';

        fetch(`https://api.countapi.xyz/hit/${namespace}/${key}`)
            .then(res => res.json())
            .then(data => {
                setViews(data.value);
            })
            .catch(err => console.error("Counter Error:", err));
    }, []);

    const counterStyle = {
        padding: '10px',
        backgroundColor: '#0056b3', // Your organization's blue
        color: 'white',
        borderRadius: '5px',
        display: 'inline-block',
        fontSize: '14px',
        fontWeight: 'bold',
        marginTop: '10px'
    };

    return (
        <div style={counterStyle}>
            Total Visitors: {views.toLocaleString()}
        </div>
    );
};

export default PageCounter;
